PROGRAM ST500_TATHETSPROV
VAR
    steg        : INT := 0;
    tmrKlamma   : TON;
    tmrFyll     : TON;
    tmrStab     : TON;
    tmrMat      : TON;
    tmrAvluft   : TON;
    tmrUtskjut  : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
    xKassera    : BOOL := FALSE;
    xTrycksatt  : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran en certifierad sakerhets-PLC och lases bara. Den har
   logiken ror inte sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);

(* Provstegens tider. Riggen fyller i 3,0 s, later trycket stabilisera sig i
   5,0 s och mater tryckfallet under 10,0 s. Klamman ska bekrafta stangt lage
   inom 2,0 s, annars sitter huset inte fast. *)
tmrKlamma(IN := steg = 1, PT := T#2s);
tmrFyll(IN := steg = 2, PT := T#3s);
tmrStab(IN := steg = 3, PT := T#5s);
tmrMat(IN := steg = 4, PT := T#10s);
tmrAvluft(IN := ST500_VLV_VENT, PT := T#1s);
tmrUtskjut(IN := ST500_PSH_REJ, PT := T#1s);

(* Sa lange huset kan vara trycksatt haller klamman kvar det. Flaggan satts nar
   fyllningen borjar och slapper forst nar avluftningen gatt sin tid. *)
IF ST500_VLV_FILL THEN
    xTrycksatt := TRUE;
END_IF;
IF tmrAvluft.Q THEN
    xTrycksatt := FALSE;
END_IF;

(* --- larmkallorna samlas fore domen, sa SYS_ALARM aldrig slapar ett scan
       efter det don den ska stanga. --- *)

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
    (* Sakerhetskretsen tar spanningen fran ventilerna. Styrningen kommenderar
       ingenting alls och far darfor inte heller pasta att den haller kvar ett
       trycksatt hus. *)
    xTrycksatt := FALSE;
END_IF;

IF tmrKlamma.Q THEN
    xLarm := TRUE;
END_IF;

(* Provtrycket ar 300 mbar overtryck. Over 330 mbar har regulatorn slappt
   igenom och ett overtrycksatt hus kan spranga tatningen. Under 270 mbar nas
   provtrycket aldrig, och da mater matfonstret ett tryckfall i ett hus som
   aldrig blev trycksatt. *)
IF steg >= 2 AND steg <= 5 AND ST500_TST_PRS > 330.0 THEN
    xLarm := TRUE;
END_IF;
IF (steg = 3 OR steg = 4) AND ST500_TST_PRS < 270.0 THEN
    xLarm := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET. Larmet slapper aldrig
   av sig sjalvt och ett aterstallt nodstopp startar ingenting. *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT EMG_OK THEN
    ST500_CNV_RUN := FALSE;
    ST500_CLP_CLOSE := FALSE;
    ST500_VLV_FILL := FALSE;
    ST500_VLV_MEAS := FALSE;
    ST500_VLV_VENT := FALSE;
    ST500_PSH_REJ := FALSE;
    ST500_TST_OK := FALSE;
    xKassera := FALSE;
    steg := 0;
ELSIF NOT xDriftsklar THEN
    (* Provet avbryts. Fyllningen och matningen stangs, huset avluftas och
       klamman haller kvar det tills trycket ar ute. Ett trycksatt hus far
       aldrig slappas ur fixturen. *)
    ST500_CNV_RUN := FALSE;
    ST500_VLV_FILL := FALSE;
    ST500_VLV_MEAS := FALSE;
    ST500_PSH_REJ := FALSE;
    ST500_TST_OK := FALSE;
    ST500_VLV_VENT := xTrycksatt;
    ST500_CLP_CLOSE := FALSE;
    xKassera := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST500_CNV_RUN := TRUE;
            ST500_CLP_CLOSE := FALSE;
            ST500_VLV_FILL := FALSE;
            ST500_VLV_MEAS := FALSE;
            ST500_VLV_VENT := FALSE;
            ST500_PSH_REJ := FALSE;
            ST500_TST_OK := FALSE;
            IF ST500_PEC_PART THEN
                ST500_CNV_RUN := FALSE;
                ST500_CLP_CLOSE := TRUE;
                steg := 1;
            END_IF;
        1:
            (* Fyllningen far borja forst nar klamman bekraftat att huset
               sitter fast mot tatningsdonet. *)
            IF ST500_CLP_CLOSED THEN
                ST500_VLV_FILL := TRUE;
                steg := 2;
            END_IF;
        2:
            IF tmrFyll.Q THEN
                ST500_VLV_FILL := FALSE;
                steg := 3;
            END_IF;
        3:
            (* Stabiliseringen. Matventilen far inte oppnas har: den
               adiabatiska uppvarmningen fran fyllningen ser ut som ett
               lackage sa lange trycket annu faller av sig sjalvt. *)
            IF tmrStab.Q THEN
                ST500_VLV_MEAS := TRUE;
                steg := 4;
            END_IF;
        4:
            IF tmrMat.Q THEN
                ST500_VLV_MEAS := FALSE;
                IF ST500_TST_DP <= 0.0 THEN
                    (* Noll tryckfall over tio sekunder ar ingen tathet utan en
                       stangd matventil eller en fastnad givare. *)
                    xLarm := TRUE;
                ELSIF ST500_TST_DP > 1.5 THEN
                    xKassera := TRUE;
                ELSE
                    ST500_TST_OK := TRUE;
                END_IF;
                ST500_VLV_VENT := TRUE;
                ST500_CLP_CLOSE := FALSE;
                steg := 5;
            END_IF;
        5:
            IF tmrAvluft.Q THEN
                ST500_VLV_VENT := FALSE;
                ST500_CLP_CLOSE := FALSE;
                steg := 6;
            END_IF;
        6:
            IF NOT ST500_CLP_CLOSED THEN
                IF xKassera AND ST500_PSH_HOME THEN
                    ST500_PSH_REJ := TRUE;
                    steg := 7;
                ELSIF NOT xKassera THEN
                    steg := 8;
                END_IF;
            END_IF;
        7:
            IF tmrUtskjut.Q THEN
                ST500_PSH_REJ := FALSE;
                steg := 8;
            END_IF;
        8:
            ST500_CNV_RUN := TRUE;
            IF NOT ST500_PEC_PART THEN
                ST500_TST_OK := FALSE;
                xKassera := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

